	dw $0016,$0018,$001A,$001C,$001E,$001E,$0020,$0020
	dw $0020,$0020,$0020,$001E,$001E,$001C,$001A,$0018
	dw $0016,$0014,$0012,$0010,$000C,$000A,$0006,$0004
	dw $0000,$FFFE,$FFFC,$FFF8,$FFF6,$FFF2,$FFF0,$FFEE
	dw $FFEC,$FFEA,$FFE8,$FFE6,$FFE4,$FFE4,$FFE2,$FFE2
