; =============================================================================
; SndPlaySongCold / SndPlaySong
; Resets every channel and global, loads preset 0 into the wave buffer and
; wave RAM, looks up the song's bank, reads the song header and the first
; sequence entries (up to and including the first pattern number).
; =============================================================================
SndPlaySongCold:
	xor a                        ; 09:67E0  AF
	ldh [rNR52],a                ; 09:67E1  E0 26     APU off/on
	ld a,$80                     ; 09:67E3  3E 80
	ldh [rNR52],a                ; 09:67E5  E0 26
SndPlaySong:
	ld a,$77                     ; 09:67E7  3E 77     warm entry
	ldh [rNR50],a                ; 09:67E9  E0 24     NR50 = $77
	ld a,$DE                     ; 09:67EB  3E DE     NR51 = $DE
	ldh [rNR51],a                ; 09:67ED  E0 25
	xor a                        ; 09:67EF  AF
	ld [wSongTranspose],a        ; 09:67F0  EA 08 CA  song transpose 0
	ld [wTickAcc],a              ; 09:67F3  EA 06 CA  row accumulator 0
	ld hl,wCh1+CH_PTR            ; 09:67F6  21 30 CA  clear $CA30-$CAFF (all four channel structs)
	ld b,$D0                     ; 09:67F9  06 D0
.l67FB
	ld [hl+],a                   ; 09:67FB  22
	dec b                        ; 09:67FC  05
	jr nz,.l67FB                 ; 09:67FD  20 FC
	ldh [rNR13],a                ; 09:67FF  E0 13
	ldh [rNR14],a                ; 09:6801  E0 14
	ldh [rNR23],a                ; 09:6803  E0 18
	ldh [rNR24],a                ; 09:6805  E0 19
	ldh [rNR33],a                ; 09:6807  E0 1D
	ldh [rNR34],a                ; 09:6809  E0 1E
	ldh [rNR43],a                ; 09:680B  E0 22
	ldh [rNR44],a                ; 09:680D  E0 23
	ld a,$FF                     ; 09:680F  3E FF     CH_DELAY_CNT = $FF
	ld [wCh1+CH_DELAY_CNT],a     ; 09:6811  EA 41 CA
	ld [wCh2+CH_DELAY_CNT],a     ; 09:6814  EA 75 CA
	ld [wCh3+CH_DELAY_CNT],a     ; 09:6817  EA A9 CA
	ld [wCh4+CH_DELAY_CNT],a     ; 09:681A  EA DD CA
	ld a,HIGH(PeriodTable)       ; 09:681D  3E 40     pitch = $4000 (CH1-3: note 0)
	ld [wCh1+CH_PITCH+1],a       ; 09:681F  EA 33 CA
	ld [wCh1+CH_NOTE_PITCH+1],a  ; 09:6822  EA 37 CA
	ld [wCh1+CH_PORTA_TGT+1],a   ; 09:6825  EA 35 CA
	ld [wCh2+CH_PITCH+1],a       ; 09:6828  EA 67 CA
	ld [wCh2+CH_NOTE_PITCH+1],a  ; 09:682B  EA 6B CA
	ld [wCh2+CH_PORTA_TGT+1],a   ; 09:682E  EA 69 CA
	ld [wCh3+CH_PITCH+1],a       ; 09:6831  EA 9B CA
	ld [wCh3+CH_NOTE_PITCH+1],a  ; 09:6834  EA 9F CA
	ld [wCh3+CH_PORTA_TGT+1],a   ; 09:6837  EA 9D CA
	ld a,$50                     ; 09:683A  3E 50     CH4 pitch = $5000 (noise index 32)
	ld [wCh4+CH_PITCH+1],a       ; 09:683C  EA CF CA
	ld [wCh4+CH_NOTE_PITCH+1],a  ; 09:683F  EA D3 CA
	ld [wCh4+CH_PORTA_TGT+1],a   ; 09:6842  EA D1 CA
	ld a,$00                     ; 09:6845  3E 00     vibrato ptr = VibratoTables, phase 0
	ld [wCh1+CH_VIB_PTR],a       ; 09:6847  EA 43 CA
	ld [wCh2+CH_VIB_PTR],a       ; 09:684A  EA 77 CA
	ld [wCh3+CH_VIB_PTR],a       ; 09:684D  EA AB CA
	ld [wCh4+CH_VIB_PTR],a       ; 09:6850  EA DF CA
	ld a,HIGH(VibratoTables)     ; 09:6853  3E 40
	ld [wCh1+CH_VIB_PTR+1],a     ; 09:6855  EA 44 CA
	ld [wCh2+CH_VIB_PTR+1],a     ; 09:6858  EA 78 CA
	ld [wCh3+CH_VIB_PTR+1],a     ; 09:685B  EA AC CA
	ld [wCh4+CH_VIB_PTR+1],a     ; 09:685E  EA E0 CA
	ld a,$40                     ; 09:6861  3E 40     CH_CTRL = $40: length enable
	ld [wCh1+CH_CTRL],a          ; 09:6863  EA 3B CA
	ld [wCh2+CH_CTRL],a          ; 09:6866  EA 6F CA
	ld [wCh3+CH_CTRL],a          ; 09:6869  EA A3 CA
	ld [wCh4+CH_CTRL],a          ; 09:686C  EA D7 CA
	ld a,$00                     ; 09:686F  3E 00     NR10 = 0
