	ld a,[wShufflePtr]           ; 09:691C  FA 0B CA
	ld l,a                       ; 09:691F  6F
	ld a,[wShufflePtr+1]         ; 09:6920  FA 0C CA
	ld h,a                       ; 09:6923  67
