; FC phase dr: shuffle (stream form; the sequence form is at $6F92).
; Phase = phase<<4 (12-bit), rate = dr & $0F, depth = dr >> 4.
Cmd_Shuffle:
	call ReadStreamByte          ; 09:6EAF  CD 03 06  phase byte
	swap a                       ; 09:6EB2  CB 37
	and $0F                      ; 09:6EB4  E6 0F
	ld h,a                       ; 09:6EB6  67
	ld a,b                       ; 09:6EB7  78
	swap a                       ; 09:6EB8  CB 37
	and $F0                      ; 09:6EBA  E6 F0
	ld [wShufflePhase],a         ; 09:6EBC  EA 0D CA
	ld a,h                       ; 09:6EBF  7C
	ld [wShufflePhase+1],a       ; 09:6EC0  EA 0E CA
	call ReadStreamByte          ; 09:6EC3  CD 03 06  depth<<4 | rate
	and $0F                      ; 09:6EC6  E6 0F
	sla a                        ; 09:6EC8  CB 27
	ld [wShuffleRate],a          ; 09:6ECA  EA 0A CA
	ld a,b                       ; 09:6ECD  78
	and $F0                      ; 09:6ECE  E6 F0
	or h                         ; 09:6ED0  B4
	add LOW(ShuffleTable)        ; 09:6ED1  C6 40
	ld [wShufflePtr],a           ; 09:6ED3  EA 0B CA
	ld a,HIGH(ShuffleTable)      ; 09:6ED6  3E 50
	adc $00                      ; 09:6ED8  CE 00
