	ld [wCh3+CH_MACRO_RET+1],a   ; 09:6F32  EA BB CA
	ld [wCh4+CH_MACRO_RET],a     ; 09:6F35  EA EE CA
	ld [wCh4+CH_MACRO_RET+1],a   ; 09:6F38  EA EF CA
	ld [wCh1+CH_WAIT],a          ; 09:6F3B  EA 54 CA
	ld [wCh2+CH_WAIT],a          ; 09:6F3E  EA 88 CA
	ld [wCh3+CH_WAIT],a          ; 09:6F41  EA BC CA
	ld [wCh4+CH_WAIT],a          ; 09:6F44  EA F0 CA
	ld a,[wSeqPtr]               ; 09:6F47  FA 04 CA
	ld l,a                       ; 09:6F4A  6F
	ld a,[wSeqPtr+1]             ; 09:6F4B  FA 05 CA
	ld h,a                       ; 09:6F4E  67
SndSeqNext:
	call ReadSongByte            ; 09:6F4F  CD F0 05
	cp $FB                       ; 09:6F52  FE FB     FB: song pan
	jr nz,.l6F92                 ; 09:6F54  20 3C
	call ReadSongByte            ; 09:6F56  CD F0 05
	and $11                      ; 09:6F59  E6 11
	ld [wCh1+CH_PAN],a           ; 09:6F5B  EA 38 CA
	ld a,b                       ; 09:6F5E  78
	and $22                      ; 09:6F5F  E6 22
	ld [wCh2+CH_PAN],a           ; 09:6F61  EA 6C CA
	ld a,b                       ; 09:6F64  78
	and $44                      ; 09:6F65  E6 44
	ld [wCh3+CH_PAN],a           ; 09:6F67  EA A0 CA
	ld a,b                       ; 09:6F6A  78
	and $88                      ; 09:6F6B  E6 88
	ld [wCh4+CH_PAN],a           ; 09:6F6D  EA D4 CA
	ld a,[wCh1+CH_DIRTY]         ; 09:6F70  FA 57 CA
	or $02                       ; 09:6F73  F6 02
	ld [wCh1+CH_DIRTY],a         ; 09:6F75  EA 57 CA
	ld a,[wCh2+CH_DIRTY]         ; 09:6F78  FA 8B CA
	or $02                       ; 09:6F7B  F6 02
	ld [wCh2+CH_DIRTY],a         ; 09:6F7D  EA 8B CA
	ld a,[wCh3+CH_DIRTY]         ; 09:6F80  FA BF CA
	or $02                       ; 09:6F83  F6 02
	ld [wCh3+CH_DIRTY],a         ; 09:6F85  EA BF CA
	ld a,[wCh4+CH_DIRTY]         ; 09:6F88  FA F3 CA
	or $02                       ; 09:6F8B  F6 02
	ld [wCh4+CH_DIRTY],a         ; 09:6F8D  EA F3 CA
	jr SndSeqNext                ; 09:6F90  18 BD
.l6F92
	cp $FC                       ; 09:6F92  FE FC     FC: shuffle
	jr nz,.l6FC7                 ; 09:6F94  20 31
	call ReadSongByte            ; 09:6F96  CD F0 05
	swap a                       ; 09:6F99  CB 37
	and $0F                      ; 09:6F9B  E6 0F
	ld d,a                       ; 09:6F9D  57
	ld a,b                       ; 09:6F9E  78
	swap a                       ; 09:6F9F  CB 37
	and $F0                      ; 09:6FA1  E6 F0
	ld [wShufflePhase],a         ; 09:6FA3  EA 0D CA
	ld a,d                       ; 09:6FA6  7A
	ld [wShufflePhase+1],a       ; 09:6FA7  EA 0E CA
	call ReadSongByte            ; 09:6FAA  CD F0 05
	and $0F                      ; 09:6FAD  E6 0F
	sla a                        ; 09:6FAF  CB 27
	ld [wShuffleRate],a          ; 09:6FB1  EA 0A CA
	ld a,b                       ; 09:6FB4  78
