	jr nz,SndStartPattern        ; 09:6FE5  20 33

; SndLoadSongHeader: song header = dw seq-start, dw pattab-start, dw length,
; db patterns, then a 3-byte-plus name block ending in $FF (ignored here).
SndLoadSongHeader:
	ld hl,SongPtrTable           ; 09:6FE7  21 80 74  hl = SongPtrTable[song]
	ld a,[wSongNum]              ; 09:6FEA  FA 00 CA
	sla a                        ; 09:6FED  CB 27
	add l                        ; 09:6FEF  85
	ld l,a                       ; 09:6FF0  6F
	ld a,h                       ; 09:6FF1  7C
	adc $00                      ; 09:6FF2  CE 00
	ld h,a                       ; 09:6FF4  67
	ld a,[hl+]                   ; 09:6FF5  2A
	ld e,a                       ; 09:6FF6  5F
	ld a,[hl]                    ; 09:6FF7  7E
	ld d,a                       ; 09:6FF8  57
	ld l,e                       ; 09:6FF9  6B
	ld h,d                       ; 09:6FFA  62
	call ReadSongByte            ; 09:6FFB  CD F0 05  wSeqPtr = start + hdr[0]
	add e                        ; 09:6FFE  83
	ld [wSeqPtr],a               ; 09:6FFF  EA 04 CA
	call ReadSongByte            ; 09:7002  CD F0 05
	adc d                        ; 09:7005  8A
	ld [wSeqPtr+1],a             ; 09:7006  EA 05 CA
	call ReadSongByte            ; 09:7009  CD F0 05  wPatTable = start + hdr[2]
	add e                        ; 09:700C  83
