	call ReadSongByte            ; 09:7010  CD F0 05
	adc d                        ; 09:7013  8A
	ld [wPatTable+1],a           ; 09:7014  EA 03 CA
	jp SndReadSequence           ; 09:7017  C3 22 6F  and read the sequence again

; Start pattern n: pattern table entry n = four words, each an offset from the
; pattern table to that channel's stream.
SndStartPattern:
	ld e,a                       ; 09:701A  5F
	ld a,l                       ; 09:701B  7D        save sequence pointer
	ld [wSeqPtr],a               ; 09:701C  EA 04 CA
	ld a,h                       ; 09:701F  7C
	ld [wSeqPtr+1],a             ; 09:7020  EA 05 CA
	ld l,e                       ; 09:7023  6B        hl = wPatTable + n*8
	ld h,$00                     ; 09:7024  26 00
	sla l                        ; 09:7026  CB 25
	rl h                         ; 09:7028  CB 14
	sla l                        ; 09:702A  CB 25
	rl h                         ; 09:702C  CB 14
	sla l                        ; 09:702E  CB 25
	rl h                         ; 09:7030  CB 14
	ld a,[wPatTable]             ; 09:7032  FA 02 CA
	ld e,a                       ; 09:7035  5F
	ld a,[wPatTable+1]           ; 09:7036  FA 03 CA
	ld d,a                       ; 09:7039  57
	add hl,de                    ; 09:703A  19
	call ReadSongByte            ; 09:703B  CD F0 05
	add e                        ; 09:703E  83
	ld [wCh1+CH_PTR],a           ; 09:703F  EA 30 CA
	call ReadSongByte            ; 09:7042  CD F0 05
	adc d                        ; 09:7045  8A
	ld [wCh1+CH_PTR+1],a         ; 09:7046  EA 31 CA
	call ReadSongByte            ; 09:7049  CD F0 05
	add e                        ; 09:704C  83
	ld [wCh2+CH_PTR],a           ; 09:704D  EA 64 CA
	call ReadSongByte            ; 09:7050  CD F0 05
	adc d                        ; 09:7053  8A
	ld [wCh2+CH_PTR+1],a         ; 09:7054  EA 65 CA
	call ReadSongByte            ; 09:7057  CD F0 05
	add e                        ; 09:705A  83
	ld [wCh3+CH_PTR],a           ; 09:705B  EA 98 CA
	call ReadSongByte            ; 09:705E  CD F0 05
	adc d                        ; 09:7061  8A
	ld [wCh3+CH_PTR+1],a         ; 09:7062  EA 99 CA
	call ReadSongByte            ; 09:7065  CD F0 05
