; =============================================================================
; SndUpdateChannel: a = channel base (low byte). Runs every update.
;   1. rows / trigger delay / retrigger
;   2. arpeggio step          3. portamento
;   4. CH3 wave upload        5. pan (note off, auto-pan, pan change)
;   6. NRx2                   7. NR10 (CH1)
;   8. frequency (transposes, glissando, vibrato, fine tune, period lookup;
;      CH4: noise index -> NR43)
;   9. NRx1 (auto-PWM or change)
;  10. clear CH_DIRTY
; =============================================================================
SndUpdateChannel:
	ld [wCurChan],a              ; 09:7081  EA 09 CA
	ld c,a                       ; 09:7084  4F
	ld h,HIGH(wCh1)              ; 09:7085  26 CA
	ld a,CH_ROWS                 ; 09:7087  3E 0F
	add c                        ; 09:7089  81
	ld l,a                       ; 09:708A  6F
	ld a,[hl+]                   ; 09:708B  2A        rows pending?
	and a                        ; 09:708C  A7
	jr z,.l70AB                  ; 09:708D  28 1C
	inc l                        ; 09:708F  2C
	ld a,[hl]                    ; 09:7090  7E
	sub $01                      ; 09:7091  D6 01     trigger-delay countdown
	ld [hl+],a                   ; 09:7093  22
	jr nc,SndChanArpeggio        ; 09:7094  30 5C
	ld a,[hl-]                   ; 09:7096  3A        expired: reload with retrigger period, CH_ROWS--
	ld [hl-],a                   ; 09:7097  32
	dec l                        ; 09:7098  2D
